from flask import Flask, request, redirect, url_for, session, render_template_string, flash
import sqlite3
from functools import wraps
from datetime import datetime

app = Flask(__name__)
app.secret_key = "CHANGE_THIS_SECRET_KEY"
DB = "online_novin.db"
ADMIN_PASSWORD = "123456"

LOGO = "data:image/jpeg;base64,"

def db():
    c = sqlite3.connect(DB)
    c.row_factory = sqlite3.Row
    return c

def init_db():
    c = db()
    c.execute("""CREATE TABLE IF NOT EXISTS requests(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        service TEXT, action TEXT, data TEXT,
        status TEXT DEFAULT 'جدید', created_at TEXT)""")
    c.commit()
    c.close()

def admin_required(f):
    @wraps(f)
    def w(*a, **k):
        if not session.get("admin"):
            return redirect("/admin/login")
        return f(*a, **k)
    return w

def save(service, action, data):
    c = db()
    c.execute("INSERT INTO requests(service,action,data,created_at) VALUES(?,?,?,?)",
              (service, action, data, datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
    c.commit()
    c.close()

