@app.route("/marriage")
def marriage():
    items = ["ثبتنام اولیه","انتخاب بانک","ویرایش اطلاعات و تلفن جدید","ویرایش شعبه","حذف درخواست","مشاهده وضعیت","بازیابی کد رهگیری"]
