@app.route("/form/<service>/<action>", methods=["GET","POST"])
def form(service, action):
    fields = FIELDS.get((service, action))
    if not fields: return "فرم پیدا نشد", 404
    if request.method == "POST":
        data = "\n".join(label+": "+request.form.get(key,"").strip() for label,key in fields)
        save("وام ازدواج" if service=="marriage" else "وام فرزندآوری", action, data)
        return page("ثبت شد", '<div class="card"><h2>درخواست با موفقیت ثبت شد ✅</h2><p>درخواست برای پنل مدیریت ارسال شد.</p><a class="btn" href="/">بازگشت</a></div>')
    inputs=""
    for label,key in fields:
        if key=="military":
            inputs += '<label>وضعیت سربازی</label><select name="military" required><option value="">انتخاب کنید</option><option>پایان خدمت</option><option>معافیت</option><option>سایر</option></select>'
        elif key=="isargari":
            inputs += '<label>ایثارگری</label><select name="isargari" required><option value="">انتخاب کنید</option><option>دارم</option><option>ندارم</option></select>'
        elif key=="bank":
            inputs += '<label>بانک موردنظر</label><select name="bank" required><option value="">انتخاب بانک</option><option>بانک ملت</option><option>بانک ملی</option><option>بانک صادرات</option><option>بانک تجارت</option><option>بانک رفاه</option><option>بانک مسکن</option><option>سایر</option></select>'
        else:
            inputs += '<label>'+label+'</label><input name="'+key+'" required>'
    back="/marriage" if service=="marriage" else "/child"
    return page(action, '<div class="card"><h2>'+action+'</h2><form method="post">'+inputs+'<button>ثبت درخواست</button></form><a class="btn gray" href="'+back+'">بازگشت</a></div>')

@app.route("/admin/login", methods=["GET","POST"])
def login():
    if request.method=="POST":
        if request.form.get("password")==ADMIN_PASSWORD:
            session["admin"]=True
            return redirect("/admin")
        flash("رمز عبور اشتباه است.")
    return page("ورود مدیریت", '<div class="card"><h2>ورود به پنل مدیریت</h2><form method="post"><label>رمز عبور</label><input type="password" name="password" required><button>ورود</button></form></div>')

@app.route("/admin/logout")
def logout():
    session.clear()
    return redirect("/")

@app.route("/admin")
@admin_required
def admin():
    c=db(); rows=c.execute("SELECT * FROM requests ORDER BY id DESC").fetchall(); c.close()
    tr=""
    for r in rows:
        data = r["data"].replace("\n","<br>")
        tr += '<tr><td>'+str(r["id"])+'</td><td>'+r["service"]+'<br>'+r["action"]+'</td><td>'+data+'</td><td>'+r["created_at"]+'</td><td><span class="badge">'+r["status"]+'</span><br><a href="/admin/status/'+str(r["id"])+"/انجام شد"+'">انجام شد</a> | <a href="/admin/status/'+str(r["id"])+"/در حال پیگیری"+'">در حال پیگیری</a><br><a href="/admin/delete/'+str(r["id"])+'" onclick="return confirm(\'حذف شود؟\')">حذف</a></td></tr>'
    return page("پنل مدیریت", '<div class="card"><h2>پنل مدیریت</h2><p>تعداد درخواست‌ها: <b>'+str(len(rows))+'</b></p><a class="btn gray" href="/admin/logout">خروج</a></div><div class="card"><h2>درخواست‌های مشتریان</h2><table><tr><th>#</th><th>خدمت</th><th>اطلاعات</th><th>زمان</th><th>وضعیت</th></tr>'+tr+'</table></div>')

@app.route("/admin/status/<int:rid>/<status>")
@admin_required
def status(rid,status):
    if status not in ("انجام شد","در حال پیگیری"): return "نامعتبر",400
    c=db(); c.execute("UPDATE requests SET status=? WHERE id=?",(status,rid)); c.commit(); c.close()
    return redirect("/admin")

@app.route("/admin/delete/<int:rid>")
@admin_required
def delete(rid):
    c=db(); c.execute("DELETE FROM requests WHERE id=?",(rid,)); c.commit(); c.close()
    return redirect("/admin")

